// Deterministic, literature-pinned per-indication benchmarks.
//
// Two model inputs were being REGENERATED by the scoring LLM on every run and
// swinging the whole waterfall: the Phase-2a surrogate comparator (historical
// control rate) and the Phase-3 registrable endpoint. This module pins both to
// published literature / regulatory precedent for indications we have verified,
// so they stop being per-run coin-flips. Indications without a verified basis
// return null and fall back to the model (unchanged behavior).
//
// Pinned to FACTS, not to a target answer: whichever direction the pinned value
// moves P(success) is a consequence of accuracy.

export type ComparatorPin = {
  nullResponseRate: number;   // historical/observation control rate for the surrogate
  comparatorSigma2: number;   // honest variance of that benchmark (heterogeneous assays/defs + single-arm-vs-historical uncertainty)
  source: string;
};

export type Phase3EndpointPin = {
  isTimeToEvent: boolean;
  endpointDescription: string;
  endpointRationale: string;
};

/** ctDNA-positive / MRD colorectal cancer in the adjuvant / post-curative-intent setting. */
export function isColorectalMRD(indication: string): boolean {
  const s = (indication || "").toLowerCase();
  const crc = /colorectal|\bcrc\b|colon|rectal/.test(s);
  const mrd = /ctdna|circulating tumor dna|\bmrd\b|minimal residual|molecular residual|curative[- ]intent|post[- ]?surg|adjuvant/.test(s);
  return crc && mrd;
}

/** Idiopathic pulmonary fibrosis (and PPF/PF-ILD phrasing variants). */
export function isIPF(indication: string): boolean {
  const s = (indication || "").toLowerCase();
  return /idiopathic pulmonary fibrosis|\bipf\b|progressive pulmonary fibrosis|\bppf\b|pf-ild|fibrosing interstitial lung/.test(s);
}

// Endpoint family the IPF pin's null actually describes (52-wk event-free responder: no ≥10%
// relative FVC decline, no death). A rate stage in an IPF program whose endpoint text names a
// DIFFERENT quantity must NOT inherit the 0.68 null — stamping a null defined for one endpoint
// onto another mis-states power by construction (8/8 code-review finding). Two-sided test:
// the text must mention the decline/progression/event-free family AND must not be an
// IMPROVEMENT-type responder (e.g. "≥5% absolute FVC improvement" contains "FVC" but its true
// null is ~0.10, not 0.68). Text absent → pin applies (legacy behavior, fires at the call site).
const IPF_FAMILY_POS = /fvc|vital capacity|event[- ]free|progression[- ]free|disease progression|decline|death|respiratory/i;
const IPF_FAMILY_NEG = /improv|increase|gain|\borr\b|objective response|overall response|complete response/i;
export function ipfEndpointFamilyMatch(endpointText: string): boolean {
  return IPF_FAMILY_POS.test(endpointText) && !IPF_FAMILY_NEG.test(endpointText);
}

/** Early (MCI / mild) Alzheimer's disease — the CDR-SB-gated disease-modification setting. */
export function isEarlyAlzheimers(indication: string): boolean {
  const s = (indication || "").toLowerCase();
  const ad = /alzheimer|\bad\b|amyloid|\btau\b/.test(s);
  const early = /early|prodromal|\bmci\b|mild|cdr|preclinical|amyloid[- ]confirmed|biomarker[- ]confirmed/.test(s);
  return ad && early;
}

/**
 * Phase-2a surrogate comparator (ctDNA-clearance historical control) for MRD+ CRC.
 *
 * CIRCULATE-Japan GALAXY (Nature Medicine 2024): spontaneous ctDNA clearance in
 * untreated observation among MRD+ CRC ≈ 1.9% sustained; transient / cross-assay
 * estimates run somewhat higher, so a ~5% central estimate. σ² is set WIDE (0.025)
 * to reflect real heterogeneity (tumor-informed vs tumor-naive assays, timepoints,
 * clearance definitions) and the single-arm-vs-historical uncertainty — replacing
 * the LLM's artificially tight ~0.018 that let a coin-flip point estimate act like
 * a hard threshold.
 *
 * @param endpointIsRate true when the stage gates on a RATE surrogate (ctDNA clearance),
 *   not a time-to-event endpoint. The comparator applies only to the rate stage.
 * @param endpointText the stage's endpoint description, when known — lets a pin whose null is
 *   defined for one endpoint family refuse a stage measuring a different one (IPF only for now;
 *   absent text keeps legacy behavior: the pin applies).
 */
export function pinComparator(indication: string, endpointIsRate: boolean, endpointText?: string): ComparatorPin | null {
  if (!endpointIsRate) return null;
  if (isIPF(indication)) {
    if (endpointText && !ipfEndpointFamilyMatch(endpointText)) return null;
    // IPF FVC responder comparator — pinned because the LLM's null DEFINITION swung across
    // otherwise-identical live runs (0.15 → 0.45 "stability rate" → 0.16 on 8/7–8/8), silently
    // re-scaling every margin. ONE definition, cited: response = event-free at 52 weeks
    // (no ≥10% relative FVC decline and no death). ASCEND (King et al., NEJM 2014): 31.8% of
    // placebo patients progressed/died → placebo event-free ≈ 68%; pirfenidone arm ≈ 83.5%
    // (a +15.5-pt margin for an approved antifibrotic ≈ μ 1.55 on the Δ=0.10 scale — the scale
    // reproduces an approved drug's observed performance, the same validation logic as 2.2).
    // INPULSIS-1/2 placebo decline (−239/−207 mL/yr) is directionally consistent. σ² honest-wide
    // for definition/trial heterogeneity — and for RCT stages it is EXCLUDED from power anyway
    // (concurrent-control rule); it locates the null and prices single-arm designs only.
    return {
      nullResponseRate: 0.68,
      comparatorSigma2: 0.008,
      source: "IPF 52-wk event-free responder null (no ≥10% rel. FVC decline or death): ASCEND placebo 68.2% event-free (King, NEJM 2014); pirfenidone 83.5%; INPULSIS-1/2 consistent. Pinned — replaces per-run LLM null-definition swings (0.15→0.45→0.16 across 8/7–8/8 live runs). σ² 0.008 is HAND-SET provisional (wide for definition/trial heterogeneity; prices single-arm designs only — excluded from RCT power), not a cited variance.",
    };
  }
  if (isColorectalMRD(indication)) {
    return {
      nullResponseRate: 0.05,
      comparatorSigma2: 0.025,
      source: "CIRCULATE-Japan GALAXY (Nat Med 2024): spontaneous ctDNA clearance in untreated MRD+ CRC ~1.9% sustained; ~5% central across assays/definitions (wide σ²).",
    };
  }
  if (isEarlyAlzheimers(indication)) {
    // Early-AD CDR-SB responder comparator. The placebo arm's clinical course is
    // well characterized: CLARITY-AD (lecanemab, NEJM 2023) and TRAILBLAZER-ALZ2
    // (donanemab, JAMA 2023) show placebo CDR-SB decline ≈ 1.5–2.0 pts / 18 mo, i.e.
    // a LOW rate of placebo patients meeting a clinically-meaningful non-decline /
    // responder threshold (~10%). σ² is honest-wide (0.010) for the responder-
    // threshold and cross-trial heterogeneity — replacing the LLM's per-run guess
    // that swung 0.08–0.35 across identical runs.
    return {
      nullResponseRate: 0.10,
      comparatorSigma2: 0.010,
      source: "CLARITY-AD (lecanemab, NEJM 2023) + TRAILBLAZER-ALZ2 (donanemab, JAMA 2023): placebo CDR-SB decline ~1.5–2.0 pts/18mo → ~10% placebo responder rate; honest σ² for responder-threshold/cross-trial heterogeneity.",
    };
  }
  return null;
}

// ── Module 3c: epidemiology pin — CITED BANDS for the eligible-patient funnel ────────────────────
// The revenue module's patient count was a single opaque number the AI asserted (8/8 v2 run: a 90k
// "global treated pool" next to a 3M prevalence claim, unsupported either way). For indications with
// well-characterized epidemiology, the library supplies cited BANDS (never points): deterministic
// code checks the stated count against the plausibility window; the checker gets the anchor to audit
// reconciliation. Facts before opinions — same doctrine as the ASCEND null and the registry-n pin.
export type EpiPin = {
  usDiagnosedLow: number;    // diagnosed patients, US
  usDiagnosedHigh: number;
  treatedPctLow: number;     // % of diagnosed on/eligible for drug therapy (real-world, not label)
  treatedPctHigh: number;
  source: string;
};

// Hand-set provisional rail: a GLOBAL accessible treated pool larger than this multiple of the US
// treated band is implausible for a specialty drug (US is typically ~35–45% of accessible value).
export const EPI_GLOBAL_TO_US_MAX = 4;

export function pinEpi(indication: string): EpiPin | null {
  if (isIPF(indication)) {
    return {
      usDiagnosedLow: 80_000,
      usDiagnosedHigh: 140_000,
      treatedPctLow: 25,
      treatedPctHigh: 45,
      source: "US IPF diagnosed prevalence ~80k–140k (claims-based estimates 42.7–63.0 per 100k adults, Raghu et al. AJRCCM claims analyses; \"~100,000 Americans\" widely cited); real-world antifibrotic uptake ~25–45% of diagnosed (US claims/registry analyses report roughly one-third treated). BANDS, not points; the ≤4× global-to-US multiple is a hand-set provisional rail.",
    };
  }
  return null;
}

/**
 * Phase-3 registrable primary endpoint for MRD+ adjuvant CRC.
 *
 * ALTAIR, DYNAMIC-III (2/3-yr RFS), CLAUDIA (3-yr DFS): the FDA-registrable PRIMARY
 * endpoint is DFS/RFS (a hard time-to-event endpoint). ctDNA clearance/negativity is
 * a supportive SECONDARY endpoint, not the registrational basis. Pinning this stops
 * the endpoint from flipping RFS↔ctDNA-rate run-to-run, and makes the surrogate→hard
 * translation penalty (Part 4) fire consistently (Ph2a rate → Ph3 TTE).
 */
export function pinPhase3Endpoint(indication: string, phase: string): Phase3EndpointPin | null {
  const isRegistration = /3|registration|pivotal/i.test(phase || "");
  if (isRegistration && isColorectalMRD(indication)) {
    return {
      isTimeToEvent: true,
      endpointDescription: "Disease-free survival (DFS) — time to recurrence or death",
      endpointRationale:
        "DFS/RFS is the FDA-registrable primary endpoint for adjuvant/MRD colorectal cancer (ALTAIR, DYNAMIC-III, CLAUDIA); ctDNA clearance is a supportive secondary, not the registrational basis. Pinned to regulatory precedent.",
    };
  }
  return null;
}
